formulas.expression:
IF(
  {!ProductosDeLaFactura_1.outputSelectedRow.Unidad_de_Medida__c} = "KG",

  /* Cálculo cuando es KG */
  IF(
    {!ProductosDeLaFactura_1.outputSelectedRow.Peso_neto__c} > 0,
    ROUND(
      {!Cantidad_Reclamada} *
      (
        {!ProductosDeLaFactura_1.outputSelectedRow.Total_con_Rapel__c} /
        {!ProductosDeLaFactura_1.outputSelectedRow.Peso_neto__c}
      ),
      0
    ),
    0
  ),

  /* Cálculo cuando NO es KG */
  IF(
    {!ProductosDeLaFactura_1.outputSelectedRow.Cantidad__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_1} *
      (
        {!ProductosDeLaFactura_1.outputSelectedRow.Total_con_Rapel__c} /
        {!ProductosDeLaFactura_1.outputSelectedRow.Cantidad__c}
      ),
      0
    ),
    0
  )
)
